pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testFuzz_property(address owner) public {
        vm.assume(owner != address(0));
        // initialize as the fuzzed actor so owner == actor
        vm.prank(owner);
        c.initialize();
        // self-transfer: transferOwnership to the current owner must succeed in P,
        // the mutant reverts because it forbids newOwner == _owner
        bool ok;
        vm.prank(owner);
        try c.transferOwnership(owner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && c.owner() == owner, "self-transfer to current owner must be allowed and ownership must persist");
    }
}
